import{d as g,C as n,o as s,c as h,E as i,a3 as a}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"屯卦","description":"第三卦·水雷屯——刚柔始交，动乎险中，万物初生，草昧未开。","frontmatter":{"title":"屯卦","description":"第三卦·水雷屯——刚柔始交，动乎险中，万物初生，草昧未开。","category":"hexagram","aliases":["屯","水雷屯"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-03.md","filePath":"yijing/hexagrams/hexagram-03.md","lastUpdated":1787800334000}'),p={name:"yijing/hexagrams/hexagram-03.md"},x=g({...p,setup(m){const r=[{id:"panhuan",term:"磐桓",pinyin:"pán huán",meaning:"磐为大石，桓为立柱；被大石压住、被柱子困住，进退不得。",context:"初九阳居下，看似受困，实为扎根。"},{id:"zhen",term:"贞",sense:1},{id:"juzhen",term:"居贞",pinyin:"jū zhēn",meaning:"安居守正，不急于动。"},{id:"jianhou",term:"建侯",pinyin:"jiàn hóu",meaning:"建立根基。同卦辞。"},{id:"zhan",term:"邅",pinyin:"zhān",meaning:"徘徊难行。"},{id:"banru",term:"班如",pinyin:"bān rú",meaning:"骑马原地盘旋、踏步不前的样子。屯卦三见「乘马班如」。"},{id:"feikou",term:"匪寇",pinyin:"fěi kòu",meaning:"不是强盗。「匪寇婚媾」：看似来犯，实为求合。"},{id:"hungou",term:"婚媾",pinyin:"hūn gòu",meaning:"婚配、结合；引申为合适的连结与合作。"},{id:"zi",term:"字",pinyin:"zì",meaning:"女子许嫁、孕育；引申为开花结果。「贞不字」即守正而未结果。"},{id:"jilu",term:"即鹿",pinyin:"jí lù",meaning:"追逐猎物，喻追逐机会。"},{id:"yu",term:"虞",pinyin:"yú",meaning:"虞人，古代掌山泽、作向导的官。「无虞」即没有向导。",context:"虞是屯出来的。"},{id:"ji",term:"几",pinyin:"jī",meaning:"苗头、端倪，通「机」。「君子几」即君子见微知著。"},{id:"she",term:"舍",pinyin:"shě",meaning:"舍弃、放弃。"},{id:"lin",term:"吝"},{id:"gao",term:"膏",pinyin:"gāo",meaning:"膏泽、精华、恩泽。「屯其膏」即精华囤积、发不出去。"},{id:"qixue",term:"泣血",pinyin:"qì xuè",meaning:"哭到流出血泪，极言困苦。"},{id:"lianru",term:"涟如",pinyin:"lián rú",meaning:"泪如涟漪、流个不停。"},{id:"zhixingzheng",term:"志行正",pinyin:"zhì xíng zhèng",meaning:"志向与行为端正。"},{id:"yiguixiajian",term:"以贵下贱",pinyin:"yǐ guì xià jiàn",meaning:"以尊贵之身屈居卑下之位。初九阳爻居下，甘居低位。"},{id:"chenggang",term:"乘刚",pinyin:"chéng gāng",meaning:"阴爻凌乘于阳爻之上。六二阴爻乘于初九阳爻之上。"},{id:"fanchang",term:"反常",pinyin:"fǎn cháng",meaning:"反于常道。十年乃字，非常规，故曰反常。"},{id:"yicongqin",term:"以从禽",pinyin:"yǐ cóng qín",meaning:"因为追逐禽兽。喻只凭欲望追，没有向导。"},{id:"shiweiguang",term:"施未光",pinyin:"shī wèi guāng",meaning:"恩泽未能广泛施展。九五之膏发不出去。"},{id:"hekchang",term:"何可长",pinyin:"hé kě cháng",meaning:"怎么能长久。上六泣血涟如，不可久长。"}],e=[{position:"初九",type:"yang",text:"磐桓，利居贞，利建侯。",xiang:"虽磐桓，志行正也。以贵下贱，大得民也。",textModern:"被大石压住、被柱子困住，看似动弹不得，却利于安居守正、建立根基。",xiangModern:"虽然受困于磐桓，但志向行为端正；以尊贵之身甘居卑下，所以大得民心。"},{position:"六二",type:"yin",text:"屯如邅如，乘马班如。匪寇婚媾，女子贞不字，十年乃字。",xiang:"六二之难，乘刚也。十年乃字，反常也。",textModern:"进退两难、原地打转，看似来犯其实求合；守正而不结果，十年后才开花。",xiangModern:"六二的困难，是因为凌乘于阳刚之上；十年才结果，是反于常道的长久守正。"},{position:"六三",type:"yin",text:"即鹿无虞，惟入于林中，君子几不如舍，往吝。",xiang:"即鹿无虞，以从禽也。君子舍之，往吝穷也。",textModern:"追逐猎物却没有向导，只会迷失林中；君子见机，不如放弃，贸然前往会有憾惜。",xiangModern:"没有向导就追鹿，是只凭欲望追逐禽兽；君子舍去，是因为前往必至困穷。"},{position:"六四",type:"yin",text:"乘马班如，求婚媾，往吉，无不利。",xiang:"求而往，明也。",textModern:"骑马原地踏步，但这次是主动寻求合道的连结；去，就吉祥，无不利。",xiangModern:"主动求合而前往，是明于时势的智慧。"},{position:"九五",type:"yang",text:"屯其膏，小贞吉，大贞凶。",xiang:"屯其膏，施未光也。",textModern:"把精华囤积起来发不出去；做小事守正吉，想做大而膏不通，凶。",xiangModern:"膏泽囤积，是因为恩泽尚未能广泛施展。"},{position:"上六",type:"yin",text:"乘马班如，泣血涟如。",xiang:"泣血涟如，何可长也。",textModern:"骑着马原地踏步，哭到流出血泪。",xiangModern:"哭到血泪涟涟，这样的处境怎么能长久呢。"}];return(u,t)=>{const o=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),d=n("DaoKeywordCards");return s(),h("div",null,[i(o,{name:"屯",fullName:"水雷屯",upper:"☵",lower:"☳",guaCi:"屯，元亨利贞。勿用有攸往，利建侯。",pinyin:["zhūn"],element:"水",direction:"北",insight:"雷在水下，欲动未动；万物初生，草昧未开，险阻在前而生机在内。",guaSlug:"03shuileitun",lines:e}),t[0]||(t[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>云雷，屯。君子以经纶。</p><p>云雷交作、尚未成雨，正是屯聚未通之象；君子由此悟到，要在混乱中理出头绪、织出秩序。</p><p>「经纶」二字——<strong>经</strong>是整理丝线、理顺经络；<strong>纶</strong>是编织、系统化。经纶，就是把混乱的丝线一根一根理顺，织成有用之物。</p><p>分形结构：</p><ul><li>经纶（丝线）→ 微观：理顺思路，整理认知</li><li>磐桓（磐石/桓柱）→ 宏观：稳固根基，建立体系</li></ul><p>磐桓不过是大些的经纶。经纶理顺，思路清；磐桓理清，侯自然立。建侯不是冲出来的，是理出来的。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>屯，刚柔始交而难生，动乎险中，大亨贞。雷雨之动满盈，天造草昧，宜建侯而不宁。</p><p>逐句释义：</p><ul><li><strong>刚柔始交而难生</strong> —— 阴阳刚柔刚开始交合，困难由此而生。这是屯的本质：初生必遇难。</li><li><strong>动乎险中，大亨贞</strong> —— 在险境中运动，正是屯的处境；但根本上是亨通的，只要守正。</li><li><strong>雷雨之动满盈，天造草昧</strong> —— 雷雨交作、充盈天地，天地造化本就从混沌草昧开始。</li><li><strong>宜建侯而不宁</strong> —— 应当建立根基，而不是急于安定。扎根，是屯卦给出的唯一正解。</li></ul><blockquote><p><strong>草昧哲学</strong>：草昧不是障碍，是历练的场。被动承受屯，屯在磨你；主动迎接屯，你在用屯。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"水",guaSlug:"03shuileitun",glossary:r,items:e}),t[1]||(t[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-磐桓-利居贞-利建侯" tabindex="-1">初九 · 磐桓，利居贞，利建侯 <a class="header-anchor" href="#初九-·-磐桓-利居贞-利建侯" aria-label="Permalink to &quot;初九 · 磐桓，利居贞，利建侯&quot;">​</a></h3><ul><li><strong>磐</strong> → 大石，厚重，稳固</li><li><strong>桓</strong> → 木 + 亘，连绵不断、永久竖立的木柱</li><li><strong>磐桓</strong> → 被大石压住，被柱子困住，动弹不得</li></ul><p>但「利居贞、利建侯」——利于安居守正，利于建立根基。</p><p><strong>以贵下贱</strong>：初九是阳爻，居卦之初，本是贵的，却甘居低位，不急于冲出。道本是贵的，但它下贱——流到最低处，让普通人都能发现并运用。不是用价值换流量，是因为合道，所以自然聚人。</p><blockquote><p>核心洞见：磐石与桓柱不是障碍，而是被迫扎根的定海神针。被压住的时候，正是扎根最深的时候。</p></blockquote><h3 id="六二-·-屯如邅如-乘马班如。匪寇婚媾-女子贞不字-十年乃字" tabindex="-1">六二 · 屯如邅如，乘马班如。匪寇婚媾，女子贞不字，十年乃字 <a class="header-anchor" href="#六二-·-屯如邅如-乘马班如。匪寇婚媾-女子贞不字-十年乃字" aria-label="Permalink to &quot;六二 · 屯如邅如，乘马班如。匪寇婚媾，女子贞不字，十年乃字&quot;">​</a></h3><ul><li><strong>屯如邅如</strong> → 进退两难，原地打转</li><li><strong>乘马班如</strong> → 骑着马，却原地踏步</li><li><strong>匪寇，婚媾</strong> → 看似是敌人，其实是在等待合适的连结</li><li><strong>女子贞不字</strong> → 守正而不开花结果</li><li><strong>十年乃字</strong> → 十年之后，终于开花结果</li></ul><p><strong>乘刚三层结构</strong>：大势之刚（时代浪潮的压力）、家庭之刚（责任与现实的压力）、内心之刚（不甘被困的觉察与挣扎）。</p><p><strong>「十年乃字」的意义</strong>：「反常也」——能长期守正本身就是非凡。那段停滞不是失败，是在等一个「合」的时机。</p><blockquote><p>不悔观：没有革竹七日，就没有龙场悟道。人生不是审判，是体验。来路的每一步，都是现在的根基。</p></blockquote><h3 id="六三-·-即鹿无虞-惟入于林中。君子几不如舍-往吝" tabindex="-1">六三 · 即鹿无虞，惟入于林中。君子几不如舍，往吝 <a class="header-anchor" href="#六三-·-即鹿无虞-惟入于林中。君子几不如舍-往吝" aria-label="Permalink to &quot;六三 · 即鹿无虞，惟入于林中。君子几不如舍，往吝&quot;">​</a></h3><ul><li><strong>即鹿</strong> → 追逐猎物（机会）</li><li><strong>无虞</strong> → 没有向导（虞人）</li><li><strong>惟入于林中</strong> → 只会迷失在树林里</li><li><strong>君子几，不如舍</strong> → 君子看到苗头，不如放弃</li><li><strong>往吝</strong> → 贸然前往，会有遗憾</li></ul><blockquote><p>核心逻辑：没有向导就贸然追逐，只会迷失。虞不是天生的，虞是屯出来的——屯的人不是在等，是在练。</p></blockquote><p>六二教<strong>守</strong>，六三教<strong>辨</strong>。守住了，还要辨清哪头鹿值得追。</p><h3 id="六四-·-乘马班如-求婚媾。往-吉-无不利" tabindex="-1">六四 · 乘马班如，求婚媾。往，吉；无不利 <a class="header-anchor" href="#六四-·-乘马班如-求婚媾。往-吉-无不利" aria-label="Permalink to &quot;六四 · 乘马班如，求婚媾。往，吉；无不利&quot;">​</a></h3><p>第二次「乘马班如」，但这次是主动寻求合道的连结。「往吉，无不利」——去，就吉祥。</p><p><strong>六二 vs 六四——同象异命</strong>：六二是被动、被压（乘刚），不知往哪走；六四是主动，知道方向，正在调头求合。</p><p><strong>「婚媾」的四个维度</strong>：人（同道者、合伙人）、方向（对的赛道）、时机（对的入场时机）、确认（内心的准备）。</p><blockquote><p>体用之辨：体不厚，用出去是散的；体厚了，用出去是聚的。临界点不是等到客观指标达到，而是等到内心自然生出「想求」的冲动。</p></blockquote><h3 id="九五-·-屯其膏-小贞吉-大贞凶" tabindex="-1">九五 · 屯其膏，小贞吉，大贞凶 <a class="header-anchor" href="#九五-·-屯其膏-小贞吉-大贞凶" aria-label="Permalink to &quot;九五 · 屯其膏，小贞吉，大贞凶&quot;">​</a></h3><ul><li><strong>屯其膏</strong> → 把最精华的东西（膏）囤积起来，发不出去</li><li><strong>小贞吉</strong> → 做小范围的事，吉</li><li><strong>大贞凶</strong> → 想做大事，但膏发不出去，凶</li></ul><p>六五的处境：阴爻居君位（不得位），上无援、下无应，孤立的君，膏流不下去。</p><p><strong>小贞吉的活法</strong>：边积累，边流通；不等完美，先发出去。文章博客是通道——写是整理地形，发是测试回响，回响是地图。</p><p><strong>大贞凶的陷阱</strong>：膏还没流通成熟，就想一步到位。大的要等膏真正流通之后，自然而然地大。</p><h3 id="上六-·-乘马班如-泣血涟如" tabindex="-1">上六 · 乘马班如，泣血涟如 <a class="header-anchor" href="#上六-·-乘马班如-泣血涟如" aria-label="Permalink to &quot;上六 · 乘马班如，泣血涟如&quot;">​</a></h3><p>第三次「乘马班如」，哭到流血、泪如涟漪。</p><p><strong>三次「乘马班如」对照</strong>：</p><table tabindex="0"><thead><tr><th>爻位</th><th>状态</th><th>结局</th></tr></thead><tbody><tr><td>六二</td><td>等（乘刚被压）</td><td>十年乃字，有出路</td></tr><tr><td>六四</td><td>动（主动求合）</td><td>往吉无不利，有出路</td></tr><tr><td>上六</td><td>困（进退不能）</td><td>泣血涟如，无出路</td></tr></tbody></table><p>上六居卦之终，下无应，既不能前、又不能退，困在屯的最深处。它不是突然跌进去的，是一点一点滑进去的——每一天都是「乘马班如」，每一天都觉得还好，直到泣血涟如。</p><blockquote><p>上六警示：不自知，才是上六真正的入口。度不是靠控，是靠觉。知道自己在哪，就是最好的度。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',32)),i(d,{title:"字词释义",items:[{term:"屯",pinyin:["zhūn"],meaning:"草木初生、破土而出之象；也指囤积、积聚。屯是暂时的困难，不是永久的困境。"},{term:"磐桓",pinyin:["pán","huán"],meaning:"磐为大石，桓为立柱；被压住、被困住，进退不得。"},{term:"邅",pinyin:["zhān"],meaning:"徘徊难行。"},{term:"班如",pinyin:["bān","rú"],meaning:"骑马原地盘旋、踏步不前的样子。"},{term:"婚媾",pinyin:["hūn","gòu"],meaning:"婚配、结合；引申为合适的连结与合作。"},{term:"字",pinyin:["zì"],meaning:"女子许嫁、孕育；引申为开花结果。"},{term:"虞",pinyin:["yú"],meaning:"虞人，古代掌山泽、作向导的官。「无虞」即没有向导。"},{term:"膏",pinyin:["gāo"],meaning:"膏泽、精华、恩泽。「屯其膏」即精华囤积、发不出去。"},{term:"经纶",pinyin:["jīng","lún"],meaning:"整理丝线、织成布帛；比喻在混乱中理出头绪、建立秩序。"},{term:"草昧",pinyin:["cǎo","mèi"],meaning:"草莽蒙昧，天地初开、万物未明的混沌状态。"},{term:"吝"},{term:"攸"}]}),t[2]||(t[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>屯卦讲的是<strong>万物初生之难</strong>。上坎（水、险）压着下震（雷、动），雷想冲出来，水压着它——生机在内，却处处受阻。</p><p>卦辞「元亨，利贞，勿用有攸往，利建侯」点明：根本上是亨通的，但要守正、不冒进、先扎根。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>屯不是叫你放弃，是叫你扎根；不是消极等待，是积极建立根基。能量不要消耗在冲动上，要转化为「根基」。</p><p>草昧不是障碍，是历练的场。被动承受屯，屯在磨你；主动迎接屯，你在用屯。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>先守正：磐桓不是坏事，是扎根的定海神针</li><li>再辨清：没有向导（虞）时，不如舍，先练成有虞之人</li><li>养体待发：体不厚，用出去是散的</li><li>让膏流通：边积累边输出，细水长流</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>屯卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>元亨利贞，勿用有攸往，利建侯</td><td>扎根，守正，建立根基</td><td>扎根</td></tr><tr><td>初九</td><td>磐桓，利居贞，利建侯</td><td>被压住时，正是扎根最深时</td><td>以贵下贱，甘居低位</td></tr><tr><td>六二</td><td>屯如邅如，乘马班如，十年乃字</td><td>守住，等字，不悔来路</td><td>乘刚三层，不悔观</td></tr><tr><td>六三</td><td>即鹿无虞，惟入于林中，不如舍</td><td>辨清方向，练成有虞之人</td><td>虞是屯出来的</td></tr><tr><td>六四</td><td>乘马班如，求婚媾，往吉</td><td>养体，等临界点，体厚再用</td><td>体用之辨，临界点自判</td></tr><tr><td>九五</td><td>屯其膏，小贞吉，大贞凶</td><td>让膏流通，细水长流</td><td>小贞吉，文章博客即虞</td></tr><tr><td>上六</td><td>乘马班如，泣血涟如</td><td>保持自知，保持想动的心</td><td>不自知是入口，觉优于控</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>草昧哲学</strong>——草昧不是障碍，是历练的场</li><li><strong>经纶与磐桓的分形</strong>——磐桓不过是大些的经纶</li><li><strong>以贵下贱</strong>——道下贱流到最低处，是因为合道所以自然聚人</li><li><strong>不悔观</strong>——人生不是审判，是体验</li><li><strong>虞是屯出来的</strong>——屯的人不是在等，是在练</li><li><strong>体用之辨</strong>——体厚了，用出去是聚的</li><li><strong>膏要流通</strong>——志越大而膏越堵，越凶</li><li><strong>上六的警示</strong>——不自知，才是真正的入口</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>屯卦对处境的自我定位，六个爻像一条成长的时间线：</p><ul><li><strong>初九</strong> → 已做到：磐桓扎根，以贵下贱，甘居低位</li><li><strong>六二</strong> → 已经历：长期停滞，外力打破，走出来了</li><li><strong>六三</strong> → 现在主体：即鹿无虞，在观察，没有深追</li><li><strong>六四</strong> → 前夜：临界点还没到，体在养，用未发</li><li><strong>六五</strong> → 部分到：膏在流通（文章博客），但求未发</li><li><strong>上六</strong> → 警示已知：自知了，门已窄</li></ul><p>两次「乘马班如」的本质区别：第一次是不自知，被外力打破；第二次是自知了，用内力觉察。上六的门，对自知的人，已经窄了很多。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：乾（第一卦）、坤（第二卦）、蒙（第四卦）</li><li>屯与蒙的连结：屯而后蒙——草昧之后，是启蒙；根扎稳了，才能真正开始学。蒙卦卦辞「匪我求童蒙，童蒙求我」——不是我去找学生，是学生来找我。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',20))])}}});export{y as __pageData,x as default};
